<script setup lang="ts">
import type { Hotel } from '#fsd/entities/hotel'
import { useCurrentUser } from '#fsd/shared/auth'
import { EmptyState, PageHeader, StatusBadge } from '#fsd/shared/ui'

const user = useCurrentUser()
const { data: hotels, refresh, status } = await useAsyncData('hotels', () => $fetch<Hotel[]>('/api/hotels'))
const { data: apartments, refresh: refreshApartments } = await useAsyncData('hotel-apartment-counts', () => $fetch<Array<{ id: string; hotel: { id: string } }>>('/api/apartments'))
const apartmentCount = (hotelId: string) => (apartments.value ?? []).filter(apartment => apartment.hotel.id === hotelId).length
const open = ref(false); const error = ref(''); const pending = ref(false)
const archivePending = ref(false); const deletePending = ref(false)
const deleteHotel = ref<Hotel | null>(null); const deleteOpen = ref(false)
const form = reactive({ name: '', address: '', latitude: 41.83, longitude: 23.49 })
async function create() { pending.value = true; error.value = ''; try { await $fetch('/api/hotels', { method: 'POST', body: form }); open.value = false; Object.assign(form, { name: '', address: '', latitude: 41.83, longitude: 23.49 }); await refresh() } catch (cause: any) { error.value = cause?.data?.statusMessage ?? 'Не удалось сохранить отель' } finally { pending.value = false } }
async function archive(hotel: Hotel) { archivePending.value = true; error.value = ''; try { await $fetch(`/api/hotels/${hotel.id}/archive`, { method: 'POST' }); await refresh() } catch (cause: any) { error.value = cause?.data?.statusMessage ?? 'Не удалось архивировать отель' } finally { archivePending.value = false } }
function askToDelete(hotel: Hotel) { error.value = ''; deleteHotel.value = hotel; deleteOpen.value = true }
async function removeHotel() { if (!deleteHotel.value) return; deletePending.value = true; error.value = ''; try { await $fetch(`/api/hotels/${deleteHotel.value.id}`, { method: 'DELETE' }); deleteOpen.value = false; deleteHotel.value = null; await Promise.all([refresh(), refreshApartments()]) } catch (cause: any) { error.value = cause?.data?.statusMessage ?? 'Не удалось удалить отель' } finally { deletePending.value = false } }
</script>

<template><section class="page-wrap space-y-6"><PageHeader title="Апарт-отели" description="Адреса объектов и привязанные апартаменты."><template #actions><UButton v-if="user?.roles.includes('administrator')" icon="i-lucide-plus" @click="open = true">Добавить отель</UButton></template></PageHeader><UAlert v-if="error && !deleteOpen" color="error" variant="soft" :description="error" /><div v-if="status === 'pending'" class="grid gap-4 md:grid-cols-2"><USkeleton v-for="item in 4" :key="item" class="h-56 rounded-2xl" /></div><div v-else-if="hotels?.length" class="grid gap-4 md:grid-cols-2"><article v-for="hotel in hotels" :key="hotel.id" class="surface p-5 sm:p-6"><div class="flex items-start justify-between gap-4"><div class="grid size-11 shrink-0 place-items-center rounded-xl bg-[var(--color-primary-soft)] text-[var(--color-primary)]"><UIcon name="i-lucide-hotel" class="size-5" /></div><StatusBadge :label="hotel.status === 'active' ? 'Активен' : 'В архиве'" :tone="hotel.status === 'active' ? 'success' : 'neutral'" /></div><h2 class="mt-5 text-xl font-semibold">{{ hotel.name }}</h2><p class="mt-2 min-h-12 text-sm leading-6 text-[var(--color-muted)]">{{ hotel.address }}</p><div class="mt-5 flex items-center justify-between border-t border-[var(--color-line)] pt-4"><p class="text-sm"><strong class="tabular-nums">{{ apartmentCount(hotel.id) }}</strong> {{ apartmentCount(hotel.id) === 1 ? 'апартамент' : 'апартаментов' }}</p><div class="flex items-center gap-1"><UButton :to="`https://www.google.com/maps/search/?api=1&query=${hotel.latitude},${hotel.longitude}`" target="_blank" color="neutral" variant="ghost" icon="i-lucide-route">Маршрут</UButton><UButton v-if="user?.roles.includes('administrator') && hotel.status === 'active'" color="neutral" variant="ghost" icon="i-lucide-archive" aria-label="Архивировать отель" :loading="archivePending" @click="archive(hotel)" /><UButton v-if="user?.roles.includes('administrator')" color="error" variant="ghost" icon="i-lucide-trash-2" aria-label="Удалить отель" @click="askToDelete(hotel)" /></div></div></article></div><EmptyState v-else icon="i-lucide-hotel" title="Отелей пока нет" description="Добавьте первый апарт-отель — после этого можно создавать апартаменты."><template v-if="user?.roles.includes('administrator')" #actions><UButton @click="open = true">Добавить отель</UButton></template></EmptyState><USlideover v-model:open="open" title="Новый отель"><template #body><form class="form-grid" @submit.prevent="create"><UFormField label="Название"><UInput v-model="form.name" class="w-full" placeholder="Например, Pine Trees" required /></UFormField><UFormField label="Полный адрес"><UInput v-model="form.address" class="w-full" placeholder="Улица, номер, Банско" required /></UFormField><div class="grid grid-cols-2 gap-4"><UFormField label="Широта"><UInput v-model.number="form.latitude" type="number" min="-90" max="90" step=".000001" required /></UFormField><UFormField label="Долгота"><UInput v-model.number="form.longitude" type="number" min="-180" max="180" step=".000001" required /></UFormField></div><p class="text-sm text-[var(--color-muted)]">Координаты используются для кнопки маршрута.</p><UAlert v-if="error" color="error" variant="soft" :description="error" /><div class="form-actions"><UButton color="neutral" variant="ghost" @click="open = false">Отмена</UButton><UButton type="submit" :loading="pending">Сохранить отель</UButton></div></form></template></USlideover><UModal v-model:open="deleteOpen" title="Удалить отель"><template #body><div class="space-y-5"><p>Отель «{{ deleteHotel?.name }}» будет удалён навсегда.</p><UAlert color="error" variant="soft" title="Это действие нельзя отменить." :description="`Будут удалены ${apartmentCount(deleteHotel?.id ?? '')} апартаментов и все их заезды, уборки, задачи, остатки, финансовые записи и фотографии.`" /><UAlert v-if="error" color="error" variant="soft" :description="error" /><div class="form-actions"><UButton color="neutral" variant="ghost" @click="deleteOpen = false">Отмена</UButton><UButton color="error" :loading="deletePending" @click="removeHotel">Удалить навсегда</UButton></div></div></template></UModal></section></template>
